# AI Office v2.4 Part C Persistent Sessions Commands Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
if(-not(Test-Path -LiteralPath $Repository -PathType Container)){throw "AI Office repository not found at E:\AI\AI-Office"}
Set-Location $Repository
$Timestamp=Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory=Join-Path $Repository ("workspace\installer-backups\v2.4-part-c-"+$Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force|Out-Null
foreach($Directory in @("config\discord-office","scripts\discord-office","docs")){New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force|Out-Null}
function Write-EmbeddedFile{param([string]$RelativePath,[string]$Base64Content);$Destination=Join-Path $Repository $RelativePath;$Parent=Split-Path -Parent $Destination;if($Parent-and-not(Test-Path $Parent)){New-Item -ItemType Directory -Path $Parent -Force|Out-Null};if(Test-Path $Destination){$BackupPath=Join-Path $BackupDirectory $RelativePath;$BackupParent=Split-Path -Parent $BackupPath;if($BackupParent-and-not(Test-Path $BackupParent)){New-Item -ItemType Directory -Path $BackupParent -Force|Out-Null};Copy-Item $Destination $BackupPath -Force};[IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content));Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green}
Write-EmbeddedFile -RelativePath "config\discord-office\command-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Reset-AIOfficeDiscordSession.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Get-AIOfficeDiscordConversationHistory.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Invoke-AIOfficeDiscordCommand.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Invoke-AIOfficeDiscordInboundMessage.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\discord-office\Test-AIOfficeDiscordPersistentSessions.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.4-Part-C-Persistent-Sessions-Commands.md" -Base64Content ""
$ScriptPaths=@(
"E:\AI\AI-Office\scripts\discord-office\Reset-AIOfficeDiscordSession.ps1",
"E:\AI\AI-Office\scripts\discord-office\Get-AIOfficeDiscordConversationHistory.ps1",
"E:\AI\AI-Office\scripts\discord-office\Invoke-AIOfficeDiscordCommand.ps1",
"E:\AI\AI-Office\scripts\discord-office\Invoke-AIOfficeDiscordInboundMessage.ps1",
"E:\AI\AI-Office\scripts\discord-office\Test-AIOfficeDiscordPersistentSessions.ps1")
foreach($ScriptPath in $ScriptPaths){$Tokens=$null;$ParseErrors=$null;[System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors)|Out-Null;if($ParseErrors.Count-gt0){throw ("Syntax error in "+$ScriptPath+": "+(($ParseErrors|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.4 Part C Persistent Sessions and Commands installed successfully." -ForegroundColor Green
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan